9	export function checkPollination(rows, varieties, range = DEFAULT_RANGE) {
10	  const byName = new Map(varieties.map((v) => [v.name, v]));
11	  const trees = rows.flatMap((row) => row.trees);
12	  const problems = [];
13	
14	  for (const tree of trees) {
15	    const variety = byName.get(tree.variety);
16	    if (variety.selfFertile) continue;
17	    const partner = trees.find(
18	      (other) =>
19	        other !== tree &&
20	        distance(tree, other) <= range &&
21	        canPollinate(byName.get(other.variety), variety),
22	    );
23	    if (!partner) problems.push({ tree, reason: `no group ${variety.group}-compatible pollinator within ${range} m` });
24	  }
25	  return problems;
26	}
