1	const REQUIRED = ['name', 'spacing', 'group'];
2	
3	export class VarietyError extends Error {}
4	
5	export function normaliseVariety(raw, index = 0) {
6	  for (const key of REQUIRED) {
7	    if (raw[key] === undefined || raw[key] === '') {
8	      throw new VarietyError(`variety #${index + 1}: missing "${key}"`);
9	    }
10	  }
11	  const spacing = Number(raw.spacing);
12	  if (!Number.isFinite(spacing) || spacing <= 0) {
13	    throw new VarietyError(`variety "${raw.name}": spacing must be a positive number of metres`);
14	  }
15	  return {
16	    name: String(raw.name),
17	    spacing,
18	    group: String(raw.group).toUpperCase(),
19	    selfFertile: Boolean(raw.selfFertile),
20	    count: raw.count === undefined ? null : Math.max(0, Math.trunc(raw.count)),
21	  };
22	}
