24	const ORDER = 'ABCDEFG';
25	
26	export function groupsCompatible(a, b) {
27	  const i = ORDER.indexOf(a);
28	  const j = ORDER.indexOf(b);
29	  if (i === -1 || j === -1) return false;
30	  return Math.abs(i - j) <= 1;
31	}
