5	export function plan(spec) {
6	  const varieties = (spec.varieties ?? []).map(normaliseVariety);
7	  const rows = layoutRows(spec.plot ?? {}, varieties);
8	  const range = spec.pollinationRange ?? DEFAULT_RANGE;
9	  const problems = checkPollination(rows, varieties, range);
10	  const counts = {};
11	  for (const row of rows) counts[row.variety] = (counts[row.variety] ?? 0) + row.trees.length;
12	  return { rows, problems, counts, total: Object.values(counts).reduce((a, b) => a + b, 0) };
13	}
