15	export function formatPlan(result) {
16	  const lines = [];
17	  for (const row of result.rows) {
18	    lines.push(`row ${String(row.index + 1).padStart(2)}  y=${row.y.toFixed(1).padStart(5)} m  ${row.variety} x${row.trees.length}`);
19	  }
20	  lines.push('');
21	  for (const [name, n] of Object.entries(result.counts)) lines.push(`${name}: ${n}`);
22	  lines.push(`total: ${result.total} trees`);
23	  if (result.problems.length === 0) {
24	    lines.push('pollination: ok');
25	  } else {
26	    lines.push(`pollination: ${result.problems.length} tree(s) without a partner`);
27	    for (const p of result.problems) {
28	      lines.push(`  ${p.tree.variety} at (${p.tree.x}, ${p.tree.y}): ${p.reason}`);
29	    }
30	  }
31	  return lines.join('\n');
32	}
