3	export function layoutRows(plot, varieties) {
4	  const { width, length, rowGap = 4, margin = 1 } = plot;
5	  if (!(width > 0) || !(length > 0)) {
6	    throw new PlotError('plot width and length must be positive');
7	  }
8	  if (varieties.length === 0) return [];
9	
10	  const usableWidth = width - margin * 2;
11	  const usableLength = length - margin * 2;
12	  const rows = [];
13	  let y = margin;
14	  let v = 0;
15	
16	  while (y <= margin + usableLength) {
17	    const variety = pickNext(varieties, v);
18	    if (!variety) break;
19	    const trees = [];
20	    for (let x = margin; x <= margin + usableWidth; x += variety.spacing) {
21	      if (variety.count !== null && variety.placed >= variety.count) break;
22	      trees.push({ variety: variety.name, x, y });
23	      variety.placed += 1;
24	    }
25	    if (trees.length > 0) rows.push({ index: rows.length, variety: variety.name, y, trees });
26	    y += Math.max(rowGap, variety.spacing);
27	    v += 1;
28	  }
29	  return rows;
30	}
31	
32	function pickNext(varieties, start) {
33	  for (const v of varieties) v.placed ??= 0;
34	  for (let k = 0; k < varieties.length; k += 1) {
35	    const candidate = varieties[(start + k) % varieties.length];
36	    if (candidate.count === null || candidate.placed < candidate.count) return candidate;
37	  }
38	  return null;
39	}
